import { useState, useEffect } from "react";
import { useAuthUserMutation } from '../../slices/usersApiSlice';
import { setCredentials } from '../../slices/authSlice';
import { toast } from "react-toastify";

import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Form, Button, Row, Col } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import FormContainer from "../../components/application/FormContainer";
import Loader from '../../components/helpers/Loader';


function LoginScreen() {

    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('')

    const dispatch = useDispatch();
    const navigate = useNavigate();

    const [authUser, { isLoading }] = useAuthUserMutation();
    const { userInfo } = useSelector((state) => state.auth);

    const { search } = useLocation();
    const sp = new URLSearchParams(search);
    const redirect = sp.get('redirect') || '/';


    useEffect(() => {
        if (userInfo) {
            navigate(redirect);
       }
   }, [userInfo, redirect, navigate])

    const submitHandler = async (e) => {
        
        e.preventDefault();
        try {
            const res = await authUser({ email, password }).unwrap();

            console.log('login cridential', res)
        
            dispatch(setCredentials({ ...res, }));
            navigate(redirect);
            
        } catch (error) {
           const errorMessage = error.data?.message || 
                        error.error?.message || 
                        error.message || 
                        'Login failed';
          toast.error(errorMessage);
        }
    };



    
  return (
      <FormContainer>
          <h1>Sign In</h1>
          <Form onSubmit={submitHandler}>
              <Form.Group controlId="email" className="my-3">
                  <Form.Label>Email Address</Form.Label>
                  <Form.Control
                      type="email"
                      placeholder="Enter email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}> 
                  </Form.Control>
              </Form.Group>  
              <Form.Group controlId="password" className="my-3">
                  <Form.Label>Password</Form.Label>
                  <Form.Control
                      type="password"
                      placeholder="Enter password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}> 
                  </Form.Control>
              </Form.Group> 
              <Button type="submit" variant="primary" className="mt-3" disabled={isLoading}>
                  Sign In
              </Button>
              {isLoading && <Loader />}
          </Form>
          <Row className="py-3">
              <Col>
                  New Customer ? <Link to={redirect? `/register?redirect=${redirect}`: '/register' }>Register</Link>
              </Col>
          </Row>
    </FormContainer>
  )
}

export default LoginScreen
